H.background();
const cam = H.cam3d({ scale: 70, dist: 9, pitch: -0.5, cy: 300 });
cam.yaw = 0.4 * t;
cam.axes(4);
const k = P.k;
function cubeEdges(s, ox) {
  const c = [
    [ox,0,0],[ox+s,0,0],[ox+s,s,0],[ox,s,0],
    [ox,0,s],[ox+s,0,s],[ox+s,s,s],[ox,s,s]
  ];
  return c;
}
function drawCube(s, ox, col, w) {
  const c = cubeEdges(s, ox);
  const E = [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]];
  for (let i = 0; i < E.length; i++) cam.line(c[E[i][0]], c[E[i][1]], { color: col, width: w });
}
drawCube(1, -2.4, H.colors.sub, 1.5);
drawCube(k, 0.6, H.colors.accent, 2.5);
const L = k, A = k*k, Vv = k*k*k;
H.text("Scale factor k: length x k, area x k^2, volume x k^3", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Left: unit cube. Right: scaled by k. Watch how fast volume grows.", 24, 52, { color: H.colors.sub, size: 13 });
H.text("k = " + k.toFixed(2) + "   length x" + L.toFixed(2) + "   area x" + A.toFixed(2) + "   volume x" + Vv.toFixed(2), 24, 76, { color: H.colors.accent2, size: 13 });
H.legend([{label:"unit cube", color:H.colors.sub},{label:"scaled (k)", color:H.colors.accent}], 24, 96);
